// Helper library for X_Delta(N) computations
SetColumns(0);

// characters trivial on the subgroup generated by Delta (Delta a list of units mod N)
function CharsTrivialOn(N, Delta)
  G := FullDirichletGroup(N);
  return [chi : chi in Elements(G) | &and[ Evaluate(chi,d) eq 1 : d in Delta]];
end function;

// subgroup of (Z/N)^* generated by gens, as a sorted list of integers
function SubgroupList(N, gens)
  U, m := UnitGroup(Integers(N));
  H := sub<U | [ (Integers(N)!g) @@ m : g in gens] cat [ (Integers(N)!(-1)) @@ m ]>;
  return Sort([ Integers()!(m(h)) : h in H ]);
end function;

// index mu of Gamma_Delta in PSL2(Z)
function MuDelta(N, Delta)
  psi := N*&*[Rationals()| 1+1/p : p in PrimeDivisors(N)];
  return Integers()!(psi * EulerPhi(N)/#Delta);
end function;

// q-expansion basis over Z of S_2(Gamma_Delta)
function QBasis(N, Delta, prec)
  chars := CharsTrivialOn(N, Delta);
  M := CuspForms(chars, 2);
  return M, qExpansionBasis(M, prec);
end function;

// relations of degree d among forms F (power series over a field K), up to precision prec
function Relations(F, d, K)
  g := #F;
  R := PolynomialRing(K, g);
  mons := MonomialsOfDegree(R, d);
  PS<q> := PowerSeriesRing(K);
  prec := Min([AbsolutePrecision(f) : f in F]);
  Fk := [PS!f : f in F];
  vals := [ Evaluate(m, Fk) : m in mons ];
  mat := Matrix(K, [ [Coefficient(v, i) : i in [0..prec-1]] : v in vals ]);
  ker := Kernel(mat);
  return [ &+[ b[i]*mons[i] : i in [1..#mons] ] : b in Basis(ker) ], R;
end function;
